# filename: scripts/smoke.py
# Code Generated by Sidekick is for learning and experimentation purposes only.
"""Deterministic synthetic API rule checks; writes isolated AWS test cards."""
import argparse
import json
import sys
import time
import uuid
from datetime import datetime, timezone
from pathlib import Path
from urllib.error import HTTPError, URLError
from urllib.parse import urlparse
from urllib.request import ProxyHandler, Request, build_opener

import boto3


def payment(token, device, amount):
    return {
        "schema_version": "1.0",
        "transaction_id": str(uuid.uuid4()),
        "event_time": datetime.now(timezone.utc).isoformat(),
        "card_token": token,
        "card_bin": "999001",
        "amount_minor": amount,
        "currency": "USD",
        "channel": "ECOM",
        "entry_mode": "ecom",
        "merchant": {
            "id": "synthetic_smoke", "mcc": "5411", "country": "US"
        },
        "device_id": device,
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--url", default="http://127.0.0.1:8080/v1/decide")
    # Retained for compatibility; generated cards are not used as fixtures.
    parser.add_argument("--cards", help="Compatibility argument; not read.")
    parser.add_argument(
        "--config",
        default=str(Path.home() / "Fraud-Detection/config/config.json"),
    )
    parser.add_argument("--confirm-synthetic", action="store_true")
    args = parser.parse_args()
    if not args.confirm_synthetic:
        parser.error("Add --confirm-synthetic for synthetic sandbox writes.")
    parsed = urlparse(args.url)
    if (
        parsed.scheme != "http"
        or parsed.hostname not in {"localhost", "127.0.0.1"}
        or parsed.username or parsed.password
        or parsed.path != "/v1/decide"
        or parsed.query or parsed.fragment
    ):
        parser.error("Use the local sandbox /v1/decide URL.")

    with open(args.config, encoding="utf-8") as source:
        cfg = json.load(source)
    threshold = cfg["rules"]["velocity_max_5m"]
    multiple = cfg["rules"]["large_amount_multiple"]
    if type(threshold) is not int or not 1 <= threshold <= 100:
        parser.error("Unsupported velocity threshold for this small test.")
    if not isinstance(multiple, (int, float)) or not 0 < multiple <= 100:
        parser.error("Unsupported large-amount threshold.")

    session = boto3.Session(region_name="us-east-1")
    if session.client(
        "sts", endpoint_url="https://sts.us-east-1.amazonaws.com"
    ).get_caller_identity()["Account"] != "215409407944":
        parser.error("Unexpected AWS account; no fixtures written.")
    table = session.resource(
        "dynamodb",
        endpoint_url="https://dynamodb.us-east-1.amazonaws.com",
    ).Table("card_features")
    opener = build_opener(ProxyHandler({}))
    failures = 0
    scenarios = [
        ("blocked", "RULE_BLOCKED", {"DECLINE"}),
        ("velocity", "RULE_VELOCITY", {"DECLINE"}),
        ("new_device", "RULE_LARGE_NEW_DEVICE", {"STEP_UP", "DECLINE"}),
    ]

    for name, expected_reason, allowed in scenarios:
        token = f"synthetic_smoke_{name}_{uuid.uuid4().hex}"
        now = int(time.time())
        recent = []
        if name == "velocity":
            # Prior events plus the current payment exceed the threshold.
            recent = [
                [now - 10, str(uuid.uuid4())] for _ in range(threshold)
            ]
        table.put_item(
            ConditionExpression="attribute_not_exists(card_token)",
            Item={
                "card_token": token,
                "known_devices": {"synthetic_known_device"},
                "blocked": name == "blocked",
                "avg_amount_30d": 50,
                "avg_n": 20,
                "recent": json.dumps(recent),
                "txn_count_5m": len(recent),
                "last_country": "US",
                "last_event_ts": now - 10,
                "updated_at": now,
            },
        )
        amount = int(5000 * (multiple + 1)) if name == "new_device" else 3000
        device = "synthetic_new_device" if name == "new_device" else "synthetic_known_device"
        body = payment(token, device, amount)
        request = Request(
            args.url,
            data=json.dumps(body).encode(),
            headers={"Content-Type": "application/json"},
        )
        try:
            with opener.open(request, timeout=10) as response:
                reply = json.load(response)
            passed = (
                reply.get("fallback") is False
                and reply.get("decision") in allowed
                and expected_reason in reply.get("reasons", [])
                and "FEATURES_STALE" not in reply.get("reasons", [])
            )
            print(
                f"{'PASS' if passed else 'FAIL'} {name}: "
                f"decision={reply.get('decision')}, "
                f"reasons={reply.get('reasons')}"
            )
        except (HTTPError, URLError, TimeoutError, ValueError):
            passed = False
            print(f"FAIL {name}: HTTP, connection, timeout, or response error.")
        failures += not passed

    print("Fixtures retained for asynchronous consumers; no cleanup performed.")
    print("OTP, model accuracy, and latency targets are not tested here.")
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())
